SUM_st.name='SUM'; 
SUM_st.lat=72.5800018311;
SUM_st.lon=-38.4799995422;
SUM_st.alt=3238;
SUM_st.env='P';
SUM_st.footp='P';
%%

SUM_rd=read_betsy_2026('C:\github_trend\raw_data\sum_2003_2025',SUM_st.name); %[output:3301dc45] %[output:1899fe14]
%%
datevec(SUM_rd.Time(1)) %[output:1db4ccec]
datevec(SUM_rd.Time(end)) %[output:0ded8098]
names=fieldnames(SUM_rd);
c=contains(names,'U');
namesU=names(c);
for i=1:length(namesU) %[output:group:016aa204]
prctile(SUM_rd.(namesU{i}),[5 50 95]) %[output:0c10314b] %[output:8f59393a] %[output:8352ba87] %[output:6c5838fe]
end %[output:group:016aa204]
%all U < 10% NO PROBLEM
plotFigControl(SUM_rd,SUM_st.name); %[output:05914bf0] %[output:5706f7a5] %[output:403c2153] %[output:1336955d] %[output:4aa4b72b] %[output:24acaef4]
% naming e.g. BsB_S11 and BsB2_S11 correspond both to TSI. The size cut of
% 2.5 was replaced by whole air in 2022
%%

% _dry are similar to other data and can be removed
names_rd=fieldnames(SUM_rd);
c=endsWith(names_rd,'dry');
names_delete=names_rd(c);

SUM_rd=removevars(SUM_rd,names_delete);
names_rd=fieldnames(SUM_rd);
%%
% break point detection: scattering
% it has to be done on the merge BsB2_S11 (PM2.5) until 23.7.2022 and
% BsB_S11 thereafter

P1=timerange('2003-01-01','2022-07-23');
P2=timerange('2022-07-23','2026-01-01');

% B

SUM_rd.BsB20_S11=NaN(size(SUM_rd.BsB_S11));
SUM_rd.BsB20_S11(P1)=SUM_rd.BsB2_S11(P1);
SUM_rd.BsB20_S11(P2)=SUM_rd.BsB_S11(P2);

%G
SUM_rd.BsG20_S11=NaN(size(SUM_rd.BsG_S11));
SUM_rd.BsG20_S11(P1)=SUM_rd.BsG2_S11(P1);
SUM_rd.BsG20_S11(P2)=SUM_rd.BsG_S11(P2);

%R
SUM_rd.BsR20_S11=NaN(size(SUM_rd.BsR_S11));
SUM_rd.BsR20_S11(P1)=SUM_rd.BsR2_S11(P1);
SUM_rd.BsR20_S11(P2)=SUM_rd.BsR_S11(P2);

names_sc_short={'BsB20_S11', 'BsG20_S11','BsR20_S11'}; %[output:06f6ea5d] %[output:6f915a60] %[output:925f1672] %[output:70eba42c] %[output:7c7e0ca8] %[output:4cf61a23] %[output:471c117d] %[output:58ea31f1] %[output:6ee7e547] %[output:7af2aa52] %[output:46d1f860] %[output:3d60e003] %[output:85416bf2] %[output:5463243c] %[output:260b0cac] %[output:3f91ce07] %[output:4756112f] %[output:6c686331] %[output:1b996a5b] %[output:70e7d79e] %[output:7d5e6f17] %[output:854228b0] %[output:4874f3cd] %[output:67ca6dd5] %[output:68f9ad3b] %[output:93476491] %[output:213f7423] %[output:40598b96] %[output:5edaecfa] %[output:839e13dd]
break_SUM_scat_pettitt=change_point_analysis_V3(SUM_rd,names_sc_short,0.05,'SUM - Pettitt','neph SC');
T_SUM_scat_pettitt=make_table_breakpoints(break_SUM_scat_pettitt,names_sc_short);

break_SUM_scat_snht=change_point_analysis_SNHT_V1(SUM_rd,names_sc_short,0.05,'SUM - SNHT','neph SC');
T_SUM_scat_snht=make_table_breakpoints(break_SUM_scat_snht,names_sc_short);
%%
% ABSORPTION try to homogeneize AE16 and clap R
%make only one time series with CLAP with PM2.5 and whole air
P1=timerange('2003-01-01','2022-07-23');
P2=timerange('2022-07-23','2026-01-01');

% B

SUM_rd.BaB20_A11=NaN(size(SUM_rd.BaB_A11));
SUM_rd.BaB20_A11(P1)=SUM_rd.BaB2_A11(P1);
SUM_rd.BaB20_A11(P2)=SUM_rd.BaB_A11(P2);

%G
SUM_rd.BaG20_A11=NaN(size(SUM_rd.BaG_A11));
SUM_rd.BaG20_A11(P1)=SUM_rd.BaG2_A11(P1);
SUM_rd.BaG20_A11(P2)=SUM_rd.BaG_A11(P2);

%R
SUM_rd.BaR20_A11=NaN(size(SUM_rd.BaR_A11));
SUM_rd.BaR20_A11(P1)=SUM_rd.BaR2_A11(P1);
SUM_rd.BaR20_A11(P2)=SUM_rd.BaR_A11(P2);

%%

px=timerange('2011-07-01','2016-07-07');
ratio=SUM_rd.BaR2_A11(px)./SUM_rd.Bac1_A81(px); %[output:4ee15fca]
ratio(abs(ratio)==Inf)=NaN;
% % figure
% % plot(SUM_rd.Time(px),ratio,'.');
% % nanmedian(ratio)
% % nanmean(ratio)
% % nanvar(ratio)
% %diffx=SUM_rd.BaR2_A11(px)-SUM_rd.Bac1_A81(px);
figure
%plot(SUM_rd.Time(px),diffx,'.');
% % nanmedian(diffx)
% % nanmean(diffx)
% % nanvar(diffx)
abs_ratio=SUM_rd.Ba1_A81.*nanmean(ratio); %=nanmedian of ratio=0.24, nanmean=0.30 better
abs_diff=SUM_rd.Ba1_A81-0.115;
hold on;
plot(SUM_rd.Time,abs_ratio,'.g');
plot(SUM_rd.Time,abs_diff,'.m');
%%

% use the ratio (from red) 
% new dataset by Betsy (longformat): CLAP from 10.5.2011: to use and corrected Ba1
% before
SUM_rd.BaRratio_A81=SUM_rd.Ba1_A81.*nanmean(ratio);
py=timerange('2005-08-13','2011-05-10');
SUM_rd.BaR_A11(py)=SUM_rd2.BaR_A81(py);
SUM_rd.BaR_A=[];

%%
lambdaSC=[450;550;700]*ones(1,4);
lambdaAE=[467;530;660]*ones(1,4);
lambdaAE7=[370 470 520 590 660 880 950];
SUM_cal=compute_exp_SSA(SUM_rd,lambdaSC, lambdaAE);
plotFigControl_cal(SUM_cal, SUM_st.name);
%%
%Questions:
%problems:


%%
SUM_tr=SUM_rd; 
SUM_tr.y=year(SUM_tr.Time);
% scat begin at the beginning of a year: 2012
%end: 2018 --> too shot for trend analysis.
%abs begin in 2006, end in 2018
P=timerange('2006-01-01','2019-01-01');
SUM_tr=SUM_tr(P,:);

% %U very low --> no trend in U and dry
names=fieldnames(SUM_tr);
c= startsWith(names,["T1";"T0";"T_";"P_";"P1_";"P0_";"N";"U";"Bs";"Bbs";"Ba1"]) | contains(names,["A81";"SUM"]);
N=names(c);
for i=1:length(N)
    SUM_tr.(N{i})=[];
end
lambdaAE=[467;530;660]*ones(1,4);
SUM_tr.expA_bg=real(-log(SUM_tr.BaB_A11./SUM_tr.BaG_A11)/log(lambdaAE(1)/lambdaAE(2)));

% compute trend only on R with AE16 and CLAP

SUM_tr.BaB_A11=[];
SUM_tr.BaR_A=[];
%%
SUM_result=all_trend_STN(SUM_tr,SUM_st);
%%
SUM_result_D=SUM_result;

